-- CE-08: default rules and one base subscription per tenant; no billing or switching.
CREATE TABLE IF NOT EXISTS biz_commercial_subscription_rule_lock (id TINYINT UNSIGNED PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS biz_commercial_subscription_rules (rule_id VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,version BIGINT UNSIGNED NOT NULL,priority INT NOT NULL,sales_scope VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,plan_code VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,plan_version BIGINT UNSIGNED NOT NULL,enabled BOOLEAN NOT NULL,payload MEDIUMTEXT NOT NULL,CONSTRAINT ce08_rule_payload CHECK(JSON_VALID(payload)),CONSTRAINT ce08_rule_plan FOREIGN KEY(plan_code,plan_version) REFERENCES biz_commercial_plan_versions(plan_code,version) ON DELETE RESTRICT ON UPDATE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS biz_commercial_subscriptions (tenant_id VARCHAR(64) PRIMARY KEY,subscription_id VARCHAR(64) NOT NULL UNIQUE,plan_code VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,plan_version BIGINT UNSIGNED NOT NULL,payload MEDIUMTEXT NOT NULL,CONSTRAINT ce08_subscription_payload CHECK(JSON_VALID(payload)),CONSTRAINT ce08_subscription_plan FOREIGN KEY(plan_code,plan_version) REFERENCES biz_commercial_plan_versions(plan_code,version) ON DELETE RESTRICT ON UPDATE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS biz_commercial_subscription_receipts (scope_id VARCHAR(96) NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,kind VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,payload MEDIUMTEXT NOT NULL,PRIMARY KEY(scope_id,request_id,kind),CONSTRAINT ce08_receipt_payload CHECK(JSON_VALID(payload))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS biz_commercial_subscription_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,request_id VARCHAR(128) NOT NULL,actor_id VARCHAR(200) NOT NULL,action VARCHAR(32) NOT NULL,reason VARCHAR(512) NOT NULL,payload MEDIUMTEXT NOT NULL,created_at DATETIME(6) NOT NULL,UNIQUE KEY ce08_audit_once(tenant_id,request_id),CONSTRAINT ce08_audit_payload CHECK(JSON_VALID(payload))) ENGINE=InnoDB;
